<script setup lang="ts">
import type { ScheduledTask } from '../../api/scheduled'; import {fmtTime,taskTypes,runStatuses} from '../../lib/format'; import EmptyState from '../common/EmptyState.vue';
defineProps<{items:ScheduledTask[];busy:Set<string>;loading:boolean}>(); const emit=defineEmits<{action:[id:number,action:'run'|'toggle'|'delete'|'edit'];refresh:[]}>();
</script>
<template><section class="panel"><div class="panel-head"><h2>已配置任务</h2><div class="panel-actions"><button id="sched-refresh" class="btn btn-sm" :disabled="loading" @click="emit('refresh')">刷新</button></div></div><div v-if="items.length" class="table-wrap"><table><thead><tr><th>名称</th><th>类型</th><th>表达式</th><th>下次执行</th><th>上次结果</th><th>启用</th><th style="text-align:right">操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id" :data-scheduled="item.id"><td><strong class="title">{{item.name}}</strong></td><td><span class="protocol">{{taskTypes[item.type]||item.type}}</span></td><td class="mono">{{item.cron}}</td><td class="mono">{{item.enabled?fmtTime(item.next_run):'已禁用'}}</td><td><span v-if="item.last_status" class="badge" :class="item.last_status">{{runStatuses[item.last_status]||item.last_status}}</span><span v-else class="hint" style="margin:0">—</span><small class="hint" style="margin:2px 0 0;display:block">{{fmtTime(item.last_run_at)}}{{item.last_message?' · '+item.last_message:''}}</small></td><td><label class="switch"><input type="checkbox" :checked="item.enabled" :disabled="busy.has('toggle:'+item.id)" data-role="toggle" :data-id="item.id" :aria-label="'启停 '+item.name" @change="emit('action',item.id,'toggle')"><i></i></label></td><td><div class="row-actions"><button class="btn btn-sm" :disabled="busy.has('run:'+item.id)||item.last_status==='running'" data-role="run" :data-id="item.id" @click="emit('action',item.id,'run')">执行</button><button class="btn btn-sm" data-role="edit" :data-id="item.id" @click="emit('action',item.id,'edit')">编辑</button><button class="icon-btn danger" :disabled="busy.has('delete:'+item.id)" data-role="del" :data-id="item.id" title="删除" @click="emit('action',item.id,'delete')">✕</button></div></td></tr></tbody></table></div><EmptyState v-else title="还没有计划任务" hint="在上方填写名称、类型与 cron 表达式后新建。" /></section></template>
